import React, { useState } from 'react';
import { Field } from 'react-final-form';
import { useTranslation } from '@getvim/translate';
import {
  AlignEnum,
  ColorNameEnum,
  SizeEnum,
  defaultTimeOptions,
  TimeOption,
  WeightEnum,
} from '../../../types';
import { Text, CheckboxInput } from '../../../atoms';

import es from './translations/es.json';
import messages from './translations/messages';
import './index.less';

interface TimingSidebarProps {
  name: string;
  timeOptions?: TimeOption[];
  onTimeOptionsSelected?: (selectedTimeOptions: TimeOption[]) => void;
}

export default function TimingSidebar({
  name,
  onTimeOptionsSelected,
  timeOptions = defaultTimeOptions,
}: TimingSidebarProps) {
  const intl = useTranslation({ es });

  const [checkboxValues, setCheckboxValues] = useState({});

  const isDominantSelected = timeOptions
    .filter((option) => option.isDominant)
    .some((dominantOption) => checkboxValues[dominantOption.name]);

  const selectedTimeOptions = (selected: any) =>
    timeOptions.filter((option) => !!selected[option.name]);

  return (
    <Field
      name={name}
      render={({ input }) => (
        <div className="timing-sidebar">
          {timeOptions.map((timeOption) => (
            <div key={timeOption.name} className="timing-sidebar__option">
              <CheckboxInput
                name={timeOption.name}
                id={timeOption.inputId}
                disabled={!timeOption.isDominant && isDominantSelected}
                checked={checkboxValues[timeOption.name]}
                onChange={({ target }) => {
                  const newValues =
                    timeOption.isDominant && target.checked
                      ? { [timeOption.name]: true }
                      : { ...checkboxValues, [timeOption.name]: target.checked };
                  setCheckboxValues(newValues);

                  input.onChange(selectedTimeOptions(newValues));
                  onTimeOptionsSelected?.(selectedTimeOptions(newValues));
                }}
              />
              <label htmlFor={timeOption.inputId}>
                <Text
                  text={intl.formatMessage(messages[timeOption.name])}
                  colorName={ColorNameEnum.ultraDark}
                  size={SizeEnum['14px']}
                  align={AlignEnum.left}
                  weight={WeightEnum.medium}
                  className="timing-sidebar__option__header"
                />
                {timeOption.description && (
                  <Text
                    text={timeOption.description}
                    colorName={ColorNameEnum.ultraDark}
                    align={AlignEnum.left}
                    className="timing-sidebar__option__description"
                  />
                )}
              </label>
            </div>
          ))}
        </div>
      )}
    />
  );
}
